            "description": "Modify app.py to use Uvicorn's production server configuration with host binding and keep-alive behavior. Add explicit exception handling for startup errors.",
            "target_files": ["backend/app.py"],
            "required_context": [],
            "dependencies": ["STEP_001B", "STEP_002A"],
            "acceptance_criteria": [
              "Server process remains running for >30 seconds without shutdown",
              "Health check endpoint returns 200 OK when accessed"
            ],
            "test_files": [],
            "test_commands": [
              ".venv/bin/python -m uvicorn backend.app:app --host 0.0.0.0 --port 8000",
              "timeout 5 bash -c 'until curl -s http://localhost:8000/healthz; do sleep 1; done'"
            ]
          }
        ]
      }
    ],
